import sys

def main():
    import sys

    def parse_type(t):
        if t == 'void':
            return 'void'
        elif t == 'errtype':
            return 'errtype'
        elif t.startswith('&'):
            return parse_type(t[1:])
        elif t.endswith('*'):
            return parse_type(t[:-1]) + '*'
        else:
            return types.get(t, 'errtype')

    def typeof(A):
        return parse_type(A)

    types = {}
    n = int(sys.stdin.readline().strip())
    for _ in range(n):
        line = sys.stdin.readline().strip()
        if line.startswith('typedef'):
            _, A, B = line.split()
            types[B] = A
        elif line.startswith('typeof'):
            _, A = line.split()
            print(typeof(A))

if __name__ == "__main__":
    main()
